wb=openpyxl.load_workbook(OUT/'occupation_transitions.xlsx',read_only=True,data_only=True)
assert wb.sheetnames[:3]==['README','Case_tasks','Figure_data']
assert set(validation_tables)<=set(wb.sheetnames)
from validation_replication import workbook_summary
recalculated=workbook_summary(OUT/'occupation_transitions.xlsx')
assert len(recalculated)==6
rows=list(wb['Case_tasks'].iter_rows(min_row=2,values_only=True));np.testing.assert_allclose([r[9] for r in rows],case_export.contribution,atol=1e-12)
ws=wb['Figure_data'];header=[c.value for c in next(ws.iter_rows(min_row=1,max_row=1))];counts={};nonblank={k:0 for k in header};sources={}
for values in ws.iter_rows(min_row=2,values_only=True):
 values=values+(None,)*(len(header)-len(values));row=dict(zip(header,values));kind=row['record_type'];counts[kind]=counts.get(kind,0)+1
 for k,v in row.items():nonblank[k]+=v is not None
 if kind=='source':sources[row['source_id']]={'citation':row['citation'],'source_location':row['source_location']}
wb.close()
assert counts==figure_data.record_type.value_counts().to_dict();assert set(sources)=={'POSTING','ONET31','SST','DOL'}
for column in ['task_id','task_label','profile_coordinate','posting_frequency','canonical_in_origin','metric','value']:
 assert nonblank[column]>0,column
verification={'status':'PASS','figure_data_rows':len(figure_data),'record_counts':counts,'nonblank_counts':nonblank,'source_records':sources,'excel_formula_parity':True}
(OUT/'verification.json').write_text(json.dumps(verification,indent=2));display(pd.DataFrame({'nonblank_cells':nonblank}));print('Verified uncensored Figure_data and citations.')
